// marshalAccessrequestAnomalyResultToAnomalyResultResponseBody builds a value
// of type *AnomalyResultResponseBody from a value of type
// *accessrequest.AnomalyResult.
func marshalAccessrequestAnomalyResultToAnomalyResultResponseBody(v *accessrequest.AnomalyResult) *AnomalyResultResponseBody {
	res := &AnomalyResultResponseBody{
		Type:        v.Type,
		Severity:    v.Severity,
		Description: v.Description,
		Confidence:  v.Confidence,
		Timestamp:   v.Timestamp,
	}
	if v.Metadata != nil {
		res.Metadata = make(map[string]any, len(v.Metadata))
		for key, val := range v.Metadata {
			tk := key
			tv := val
			res.Metadata[tk] = tv
		}
	}

	return res
}
